import{_ as n,l as i,o as t,c as s,v as p,p as d,x as l,d as r,i as E,S as h,b as e}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"早退与自适应计算","description":"","frontmatter":{"title":"早退与自适应计算","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/early-exit-adaptive.md","filePath":"llm/early-exit-adaptive.md","lastUpdated":1789023840000}'),m={name:"llm/early-exit-adaptive.md"};function c(u,a,A,B,f,C){const o=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=p('<h1 id="早退与自适应计算" tabindex="-1">早退与自适应计算 <a class="header-anchor" href="#早退与自适应计算" aria-label="Permalink to &quot;早退与自适应计算&quot;">​</a></h1><div class="epigraph"><p>简单例子不必走完全深；在中间层接出分类头，用置信度决定是否停止前向。</p><footer>—— Xin et al., DeeBERT, ACL 2020；序列生成中的自适应见 Schuster et al., Confident Adaptive Language Modeling, 2022</footer></div><p><a href="/llm/looped-transformer">上一课</a>用全局 \\(T\\) 调计算，所有 token、所有样本同深。<a href="/llm/universal-transformer-recurrence">Universal Transformer</a> 的 ACT 已经按位置停机，但绑在共享块上。本课把早退接到<strong>普通不共享深层栈</strong>：中间层挂出口，推理时按置信度退出。这是部署侧的自适应计算，不必把模型改成循环体。下一课 ALBERT 回到参数共享，不再谈按例停机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加深对难例有用，对易例浪费。语言模型里大量 token 是高频、局部可预测的，少数 token 需要全深。缺口是训练与推理一致的出口：中间表示必须已经能出词表或类别，且退出决策不能系统性地伤害尾部质量。</p><p>DeeBERT 对编码器分类在若干层接分类头，用熵或置信阈值早退。CALM 把类似想法接到自回归生成：每个 token 在中间层预测，置信则退出该 token 的剩余层。二者都要解决「出口头怎么训」和「阈值怎么定」。</p><p><span class="marginnote">早退切的是深度，不是序列长度，也不是 KV 是否共享。YOCO、CLA 省的是缓存；早退省的是这一次前向还要不要算后面的 FFN 与注意力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在层集 \\(\\mathcal{L}_{\\mathrm{exit}}\\) 上接共享或独立的输出头。训练策略两种：所有出口都对真标签算损失（联合训练），或先训满深再冻骨干训出口。联合训练让浅层表示也对齐任务，早退才有东西可用；只训深层则浅出口是后贴的探针，阈值很难稳。</p><p>推理：若出口 \\(k\\) 的 \\(\\max p\\) 或 \\(1-H(p)\\) 超过阈值则停止，否则继续。阈值可按层设，使浅层更严、深层更松。生成式 CALM 还要处理 KV：早退的 token 若没算深层注意力，深层缓存缺条目，后续 token 读深层时对不齐——必须规定早退 token 仍把某一层的 KV 投影到深层，或禁止在需要满缓存的解码器上按 token 不同深。</p><h3 id="与-act、loop-的关系" tabindex="-1">与 ACT、loop 的关系 <a class="header-anchor" href="#与-act、loop-的关系" aria-label="Permalink to &quot;与 ACT、loop 的关系&quot;">​</a></h3><p>ACT 把停机学进共享块内部。早退把停机放在固定层之间的出口，实现简单，和现有检查点兼容。Loop 的 \\(T\\) 是全局预算。三者都是自适应计算族，切的轴分别是共享迭代、层号、全局循环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浅层表示偏词汇与局部，深层偏长程与任务。联合损失迫使浅层也长出一个「够用就走」的决策面。置信校准往往不足：softmax 最大概率不能直接当正确率，阈值要在验证集按代价（延迟对准确）扫。过自信导致系统性早退错误，尤其是罕见格式与否定。</p><p>编码器分类没有 KV 对齐问题，早退最干净。自回归解码器的 KV 契约是主要工程边界，也是许多论文只在编码器或非自回归设置里报加速的原因。</p><p><span class="marginnote">投机解码也是「浅网提议、深网验证」，但是两套模型或一套加草稿头，不是同一前向里的中间出口。不要把早退写成投机。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>加速比等于平均退出层对 \\(L\\) 的比，尾部难 token 仍跑满，延迟分位数改善小于均值。训练多出口会轻微拖累满深准确，这是税。阈值随领域漂，部署要按任务重扫。下一课不再用出口换计算，而用跨层共享换参数量——早退的头在共享层上会变成同一头的多次接入，语义不同。</p>',18)),(t(),d(h,null,{default:l(()=>[E(o,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E5%B1%821%22%5D%20--%3E%20E1%5B%22%E5%87%BA%E5%8F%A31%22%5D%0A%20%20E1%20--%3E%7C%22%E7%BD%AE%E4%BF%A1%E4%B8%8D%E8%B6%B3%22%7C%20L2%5B%22%E5%B1%822%22%5D%0A%20%20L2%20--%3E%20E2%5B%22%E5%87%BA%E5%8F%A32%22%5D%0A%20%20E2%20--%3E%7C%22%E7%BD%AE%E4%BF%A1%E4%B8%8D%E8%B6%B3%22%7C%20LD%5B%22%E6%9C%80%E6%B7%B1%E5%B1%82%22%5D%0A%20%20E1%20--%3E%7C%22%E8%B6%B3%E5%A4%9F%22%7C%20Out%5B%22%E8%BE%93%E5%87%BA%22%5D%0A%20%20E2%20--%3E%20Out%0A%20%20LD%20--%3E%20Out%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"早退在固定深层栈的中间出口按置信停机，按例分配深度。"),e("li",null,"联合训练各出口才能让浅层表示可退出；只探针不够。"),e("li",null,"自回归 KV 对齐是解码器早退的硬边界；编码器分类更干净。"),e("li",null,"与 ACT、循环 \\(T\\)、投机解码分属不同机制。"),e("li",null,"出处：Xin et al., ACL 2020；Schuster et al., 2022。")],-1))])}const x=n(m,[["render",c]]);export{T as __pageData,x as default};
